		public int? MaxLength { get; private set; }

		public int? DecimalPlaces { get; private set; }

		public bool UseFnc1 { get; private set; }

		public bool AsDateTime { get; private set; }

		internal AI(AIType type, string starter, string description, int? length, int? minLength, int? maxLength, int? decimalPlaces, bool useFnc1, bool asDateTime)
		{
			Type = type;
			Starter = starter;
			Description = description;
			Length = length;
			MinLength = minLength;
			MaxLength = maxLength;
			DecimalPlaces = decimalPlaces;
			UseFnc1 = useFnc1;
			AsDateTime = asDateTime;
		}

		public override string ToString()
		{
			return (string.Format("{0}({1})", Type, Starter));
		}

