		internal static string ApplyDecimalPlaces(string value, int decimanPlaces)
		{
			if(decimanPlaces >= value.Length)
				value = String.Concat(new String('0', decimanPlaces - value.Length + 1), value);

			return (value.Insert(value.Length - decimanPlaces, ","));
		}

		internal static string NormalizeDatetimeFormat(string value)
		{
			if(value == null)
				throw new ArgumentNullException("value");
			if(value.Length != 6)
				throw new ArgumentException("Некорректная длина строки. Должно быть 6 символов", "value");

			int year = int.Parse(value.Substring(0, 2));
			int month = int.Parse(value.Substring(2, 2));
			int day = int.Parse(value.Substring(4, 2));

			year += (year < 67) ? 2000 : 1900;

			if (month == 0)
				month = 12;
			if (day == 0)
				day = DateTime.DaysInMonth(year, month);

			return (String.Format("{0:D4}-{1:D2}-{2:D2}", year, month, day));
		}
